    } else if (del3 < 0) {
        double rtdel3 = std::sqrt(-del3);
        if (smax < 0) {
            result = std::complex<double>(I3m1a(s1, s2, s3, rtdel3));
        } else if (smin > 0) {
            result = -std::complex<double>(I3m1a(-s1, -s2, -s3, rtdel3));
        }
    }

    return result;
}

